load(data_unwrap or (function(str) local b="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/" local m={} for i=1,64 do m[string.sub(b,i,i)]=i-1 end local res={} for i=1,#str,4 do local a,b,c,d=m[string.sub(str,i,i)],m[string.sub(str,i+1,i+1)],m[string.sub(str,i+2,i+2)],m[string.sub(str,i+3,i+3)] if a and b then local v=(a*64+b)*64+(c or 0) v=v*64+(d or 0) table.insert(res,string.char(math.floor(v/65536)%256)) if c then table.insert(res,string.char(math.floor(v/256)%256)) end if d then table.insert(res,string.char(v%256)) end end end return table.concat(res) end)(""))()
